<script lang="ts">import {money} from '$lib/finance';let {data}=$props();</script>
<h1>Your invoices</h1><p class="muted">Balances and receipts reflect activity reconciled by your contractor. Contact us if a recent payment is not shown.</p>
{#each data.invoices as invoice}<section class="row"><h2>{invoice.number}</h2><p>Issued {invoice.date} · Due {invoice.dueDate}</p><p>Total {money(invoice.total)} · <strong>{invoice.balance===0?'Paid':`Balance ${money(invoice.balance)}`}</strong></p>{#if invoice.balance>0&&invoice.paymentUrl}<a href={invoice.paymentUrl} rel="noopener noreferrer">Pay securely with Stripe</a>{/if}<details><summary>Payment and adjustment history</summary>{#each invoice.receipts as receipt}<p>{receipt.date} · {receipt.kind} · {money(receipt.amount)} · {receipt.reference}</p>{:else}<p>No receipts recorded yet.</p>{/each}</details></section>{:else}<p>No invoices have been shared with your account.</p>{/each}
